(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.PolynomialLesson,num=window.LinearLesson,ns='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);}
function tick(n,left,top){const e=document.createElement('span');e.className='transform-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#poly-ticks').append(e);}
for(let n=-5;n<=5;n++){const p=core.point(n,n);svg('line',{x1:p.x,x2:p.x,y1:30,y2:330},$('#poly-grid'));svg('line',{x1:30,x2:330,y1:p.y,y2:p.y},$('#poly-grid'));tick(n,p.x/3.6,53);if(n!==0)tick(n,47,p.y/3.6);}
function draw(){const m=Number($('#power-left').value),n=Number($('#power-right').value),a=$('#negative-leading').checked?-1:1,root=Number($('[name="inspect-root"]:checked').value),multiplicity=root===-1?m:n,tail=core.tails(a,m,n);$('#power-left-output').value=m;$('#power-right-output').value=n;const commands=[];for(let i=0;i<=600;i++){const x=-5+i/60,p=core.point(x,core.value(a,m,n,x));commands.push(`${i===0?'M':'L'}${p.x} ${p.y}`);}$('#poly-curve').setAttribute('d',commands.join(' '));math($('#poly-equation'),`p(x)=${a<0?'-':''}(x+1)${m===1?'':'^{'+m+'}'}(x-2)${n===1?'':'^{'+n+'}'}`);$('#degree-feedback').innerHTML=`Derajatnya <span data-tex="${m+n}"></span>, koefisien utamanya <span data-tex="${a}"></span>. Ada dua akar real berbeda: <span data-tex="-1"></span> berkelipatan <span data-tex="${m}"></span>, dan <span data-tex="2"></span> berkelipatan <span data-tex="${n}"></span>.`;for(const [side,id] of [[-1,'left-sample'],[1,'right-sample']]){const s=core.sample(a,m,n,root,side);math($('#'+id),`p\\left(${num.fractionTex(num.rational(root*4+side,4))}\\right)=${num.fractionTex(num.rational(s.numerator,s.denominator))}`);}$('#sign-feedback').innerHTML=`Akar <span data-tex="${root}"></span> berkelipatan <span data-tex="${multiplicity}"></span> (${multiplicity%2===0?'genap':'ganjil'}). `+(multiplicity%2===0?'Nilai di kedua sisi bertanda sama. Grafik menyentuh sumbu mendatar lalu kembali ke sisi yang sama.':'Nilai di kedua sisi bertanda berbeda. Grafik memotong sumbu mendatar, meskipun bisa tampak mendatar di sekitar akar berkelipatan tiga.');$('#left-end').textContent=tail.left>0?'Naik tanpa batas':'Turun tanpa batas';$('#right-end').textContent=tail.right>0?'Naik tanpa batas':'Turun tanpa batas';$('#poly-plot').setAttribute('aria-label',`Polinomial dengan koefisien utama ${a}, akar negatif satu berkelipatan ${m} dan akar dua berkelipatan ${n}. Derajat ${m+n}. Dekat akar yang diperiksa ${root}, grafik ${multiplicity%2===0?'menyentuh tanpa berubah tanda':'memotong dan berubah tanda'}.`);}
['power-left','power-right'].forEach(id=>$('#'+id).addEventListener('input',draw));$('#negative-leading').addEventListener('change',draw);document.querySelectorAll('[name="inspect-root"]').forEach(e=>e.addEventListener('change',draw));$('#reset-poly').addEventListener('click',()=>{$('#power-left').value=2;$('#power-right').value=1;$('#negative-leading').checked=false;$('[name="inspect-root"][value="-1"]').checked=true;draw();});draw();
const questions=[{tex:'p(x)=2x^4-3x^2+7',prompt:'Berapa derajat polinomial ini?',n:4,hint:'Cari pangkat terbesar dengan koefisien bukan nol.',why:'Pangkat terbesar adalah empat. Suku lain tidak mengubah derajat itu.'},{tex:'p(x)=-3(x+1)^2(x-2)^3',prompt:'Berapa derajat polinomial ini?',n:5,hint:'Kalikan suku utama tiap faktor: pangkatnya dijumlahkan.',why:'Derajat faktor pertama dua dan faktor kedua tiga, sehingga jumlah derajatnya lima. Koefisien utama negatif tiga bukan derajat.'},{tex:'p(x)=(x-2)^3(x+1)',prompt:'Berapa kelipatan akar dua?',n:3,hint:'Perhatikan pangkat faktor yang nol pada masukan dua.',why:'Faktor masukan dikurangi dua muncul tiga kali. Faktor lainnya tidak nol pada masukan dua, sehingga kelipatannya tepat tiga.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 3.':'Belum tepat. Bedakan derajat, koefisien utama, dan kelipatan akar.');}));
const choices=[{tex:'p(x)=(x+1)^2(x-2)',prompt:'Apa yang terjadi di sekitar akar negatif satu?',options:['Grafik selalu memotong karena derajat totalnya ganjil.','Grafik menyentuh dan tidak berubah tanda karena kelipatan akarnya genap.','Grafiknya tidak terdefinisi pada akar.'],answer:1,why:'Perilaku dekat akar ditentukan kelipatan faktor akar itu, bukan paritas derajat total. Faktor berpangkat dua tidak berubah tanda.'},{tex:'p(x)=-2x^5+x^2-1',prompt:'Bagaimana perilaku jauh di kedua ujung grafik?',options:['Kiri naik tanpa batas, kanan turun tanpa batas.','Kiri turun tanpa batas, kanan naik tanpa batas.','Kedua ujung naik tanpa batas.'],answer:0,why:'Derajat ganjil membuat kedua ujung berlawanan arah. Koefisien utama negatif membuat ujung kanan turun dan ujung kiri naik.'},{tex:'p(x)=(x-1)^4',prompt:'Berapa akar real berbeda yang dimiliki polinomial ini?',options:['Empat akar real berbeda.','Tidak ada akar real.','Satu akar real berbeda, dengan kelipatan empat.'],answer:2,why:'Hanya masukan satu yang membuat faktor nol. Derajat empat tidak berarti empat akar real berbeda; akar yang sama dapat berulang.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}">${o}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-polynomial-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-polynomial-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();